def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "lift_stack": And([
            Not(self.stack_even),
            Not(self.sensor_used),
            self.load_balance_sensor_available,
            self.autonomous_adjustment_enabled
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
